            + "(i.e., the number of key/value parameters (%s) must be even).",
        rest.length + 2);

<COVER>    Map<@Nullable Object, @Nullable Object> expectedMap = Maps.newLinkedHashMap();
<COVER>    expectedMap.put(k0, v0);
<COVER>    Multiset<@Nullable Object> keys = LinkedHashMultiset.create();
<COVER>    keys.add(k0);
<COVER>    for (int i = 0; i < rest.length; i += 2) {
<COVER>      Object key = rest[i];
<COVER>      expectedMap.put(key, rest[i + 1]);
<COVER>      keys.add(key);
