  public final void doesNotContainEntry(@Nullable Object key, @Nullable Object value) {
    checkNoNeedToDisplayBothValues("entrySet()")
        .that(checkNotNull(actual).entrySet())
        .doesNotContain(immutableEntry(key, value));
